mapper.select:
SELECT alarm_incident.id, alarm_incident.tenant_id, alarm_incident.rule_id, alarm_incident.organization_id, alarm_incident.device_id, alarm_incident.meter_id, alarm_incident.parameter_id, alarm_incident.severity, alarm_incident.state, alarm_incident.trigger_value, alarm_incident.latest_value, alarm_incident.occurrence_count, alarm_incident.opened_at, alarm_incident.last_observed_at, alarm_incident.acknowledged_by, alarm_incident.acknowledged_at, alarm_incident.cleared_at, alarm_incident.version, alarm_incident.updated_at, NULL::text AS organization_path FROM alarm_incident WHERE alarm_incident.device_id = #{deviceId} AND alarm_incident.state IN
#{state}
ORDER BY alarm_incident.opened_at DESC, alarm_incident.id LIMIT #{limit}
